import { createFactKey } from './fact-key.0f9d5b48a24e.js';
const NON_MAIN = new Set(['memory','quote','dream','hypothetical','hearsay','plan']);
function result(candidate, disposition, reasonCode, normalizedValue = candidate.value) { const factKey = createFactKey(candidate); return { ...candidate, disposition, reasonCode, normalizedValue, factKey, requiresPlayerDecision: disposition === 'pending' }; }
function isPlayer(candidate) { return candidate.subjectRef.entityId === 'entity:player' || candidate.subjectRef.role === 'player' || candidate.value.ownerEntityId === 'entity:player'; }
function displayOnly(quote) { return /(?:\u5c55\u793a|\u5546\u5e97|\u67e5\u770b|\u770b\u5230|\u63d0\u5230|\u6a94\u6848|\u8a18\u9304|\u5c6c\u65bc|\u6301\u6709)/.test(quote); }
export function classifyCandidate(candidate, { state = { events: [] } } = {}) { const factKey = createFactKey(candidate); if (state.events?.some((event) => event.deletedAt === null && event.factKey === factKey)) return result(candidate, 'suppress', 'duplicate_committed_fact'); if (NON_MAIN.has(candidate.timelineContext)) return result(candidate, 'suppress', 'non_main_timeline'); if (candidate.kind === 'inventory') { if (displayOnly(candidate.evidence.quote)) return result(candidate, 'discard', 'display_or_mention_only'); if (!isPlayer(candidate)) return result(candidate, 'pending', 'inventory_owner_missing_or_not_player'); const quantity = candidate.value.quantity; if (quantity.exact === null && !quantity.text) return result(candidate, 'pending', 'inventory_quantity_missing'); return result(candidate, 'apply', 'explicit_player_inventory'); } if (candidate.kind === 'currency' && candidate.value.amount === null) return result(candidate, 'pending', 'currency_amount_missing'); if (candidate.kind === 'person_state' && candidate.value.identityAmbiguous) return result(candidate, 'pending', 'person_identity_ambiguous'); if (candidate.kind === 'relationship' && !candidate.value.targetEntityId && !candidate.value.targetName) return result(candidate, 'pending', 'relationship_target_missing'); return result(candidate, 'apply', 'complete_local_schema'); }
